<template>
  <div class="observation-results">
    <article v-for="result in results" :key="result.conversationId" class="result-card">
      <header class="result-header"><div class="person-heading"><span class="person-icon"><v-icon size="22">mdi-account-outline</v-icon></span><div><h3>{{ result.employees.map(u=>u.name).join(', ') || 'Chưa xác định nhân viên' }}</h3><p>{{ result.title || 'Kết quả phân tích hội thoại' }}</p></div></div><v-chip size="small" :color="result.error || result.status!=='COMPLETED' ? 'secondary' : hasIssues(result) ? 'warning' : 'success'" variant="tonal">{{ result.error || result.status!=='COMPLETED' ? 'Chưa phân tích được' : hasIssues(result) ? 'Cần xem xét' : 'Đã phân tích' }}</v-chip></header>
      <div v-if="result.error" class="blocked-result"><v-icon size="22">mdi-pause-circle-outline</v-icon><div><strong>{{ qcError(result.error) }}</strong><p>Chưa có nhận xét hoặc bằng chứng từ AI cho hội thoại này.</p></div></div>
      <template v-else>
        <p class="result-summary">{{ result.summary }}</p>
        <div v-if="result.missingContext?.length" class="missing-context">{{ result.missingContext.map(qcError).join(' ') }}</div>
        <div v-for="finding in orderedFindings(result)" :key="finding.type" :class="['finding-card',{'needs-review':finding.status==='POTENTIAL_ISSUE'}]">
          <div class="finding-header"><h4><v-icon size="17">{{ finding.status==='POTENTIAL_ISSUE'?'mdi-message-alert-outline':'mdi-text-box-check-outline' }}</v-icon>{{ qcLabel(finding.type) }}</h4><v-chip size="small" :color="qcTone(finding.status)" variant="tonal">{{ qcLabel(finding.status) }}</v-chip></div>
          <p v-if="finding.status==='POTENTIAL_ISSUE'" class="finding-person">Nhân viên liên quan: <strong>{{ finding.employees.map(u=>u.name).join(', ') || 'Chưa đủ căn cứ xác định nhân viên' }}</strong></p>
          <p class="finding-explanation">{{ finding.explanation }}</p>
          <div v-if="finding.evidence.length" class="evidence-list"><div v-for="message in finding.evidence" :key="message.id" class="evidence-quote"><div class="quote-meta"><strong>{{ message.employee?.name || qcLabel(message.role) }}</strong><time>{{ formatTime(message.occurredAt) }}</time></div><blockquote>{{ message.text }}</blockquote></div></div>
          <details v-if="finding.citations.length" class="rule-details"><summary><v-icon size="16">mdi-book-open-page-variant-outline</v-icon> Quy tắc đối chiếu ({{ finding.citations.length }})</summary><div v-for="citation in finding.citations" :key="citation.documentId+':'+citation.quote" class="rule-quote"><strong>{{ citation.sourcePath || 'Tài liệu đã duyệt' }} · Phiên bản {{ citation.revision }}</strong><blockquote>{{ citation.quote }}</blockquote></div></details>
          <p v-if="finding.missingContext.length" class="missing-context">{{ finding.missingContext.map(qcLabel).join(' · ') }}</p>
        </div>
      </template>
      <footer v-if="result.runId"><span>{{ result.createdAt ? formatTime(result.createdAt) : '' }} · {{ qcLabel(result.reviewStatus) }}</span><span class="result-id">{{ result.runId.slice(0,8) }}</span></footer>
    </article>
  </div>
</template>
<script setup lang="ts">
import {qcError,qcLabel,qcTone} from './presentation';
import type {ObservationResult} from './observation-types';
defineProps<{results:ObservationResult[]}>();
const hasIssues=(result:ObservationResult)=>result.findings?.some(f=>f.status==='POTENTIAL_ISSUE')??false;
const orderedFindings=(result:ObservationResult)=>[...(result.findings??[])].sort((a,b)=>Number(b.status==='POTENTIAL_ISSUE')-Number(a.status==='POTENTIAL_ISSUE'));
const formatTime=(time:string)=>new Date(time).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
</script>
<style scoped>
