;font-size:12px}.rule-details summary{display:flex;gap:6px;align-items:center;cursor:pointer;color:#5c78d0}.rule-quote{padding:12px;margin-top:10px;background:rgba(120,140,170,.05);border-radius:8px}.rule-quote strong{font-size:11px}.missing-context{font-size:11px;color:var(--qc-muted,#758096);margin:12px 20px;line-height:1.7}.finding-card .missing-context{margin:12px 0 0}footer{display:flex;justify-content:space-between;padding:12px 20px;border-top:1px solid rgba(127,145,175,.13);font-size:11px;color:var(--qc-muted,#758096)}.result-id{font-family:monospace}@media(max-width:600px){.result-header{align-items:flex-start;flex-direction:column}.finding-header{align-items:flex-start;flex-wrap:wrap}.finding-card{margin:12px;padding:12px}.person-heading h3{font-size:14px}.quote-meta{flex-wrap:wrap}}
</style>
